-- Тема 15: Неисправности и условия эксплуатации — топик id=15, категория id=14
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(14,15,'Разрешена ли эксплуатация ТС при неисправности рабочей тормозной системы?',
'["Запрещена","Разрешена при движении на малой скорости","Разрешена вне населённых пунктов","Разрешена в течение суток для доезда до сервиса"]'::jsonb,0,
'Эксплуатация ТС запрещена при неисправности рабочей тормозной системы, так как это напрямую влияет на безопасность движения.',1),
(14,15,'Что должен сделать водитель при возникновении в пути неисправности стеклоочистителя во время дождя?',
'["Устранить неисправность, а если это невозможно — прекратить дальнейшее движение","Продолжать движение с открытым окном","Продолжать движение без ограничений","Включить аварийную сигнализацию и ехать дальше"]'::jsonb,0,
'При возникновении в пути неисправности стеклоочистителя со стороны водителя во время дождя или снегопада водитель должен принять меры к устранению неисправности, а если это невозможно, то он не имеет права дальнейшего движения.',2),
(14,15,'Разрешена ли эксплуатация ТС с негорящими фарами и задними габаритными огнями в тёмное время суток?',
'["Запрещена","Разрешена при наличии дневных ходовых огней","Разрешена, если светит луна","Разрешена в течение первого часа после захода солнца"]'::jsonb,0,
'В тёмное время суток и в условиях недостаточной видимости эксплуатация ТС при неисправных или отсутствующих внешних световых приборах запрещена.',3),
(14,15,'Что запрещается устанавливать на транспортном средстве спереди?',
'["Световые приборы и световозвращающие устройства красного цвета","Световые приборы белого цвета","Дневные ходовые огни","Указатели поворота"]'::jsonb,0,
'Спереди ТС запрещается устанавливать световые приборы и световозвращающие устройства красного цвета, а также приборы, не соответствующие требованиям к цвету.',4),
(14,15,'Разрешена ли эксплуатация ТС при неисправности рулевого управления?',
'["Запрещена","Разрешена на короткие расстояния","Разрешена, если водитель опытный","Разрешена при движении по прямой"]'::jsonb,0,
'Неисправность рулевого управления является одной из наиболее опасных и категорически запрещает эксплуатацию ТС.',5),
(14,15,'Что делать водителю, если во время движения загорелся сигнал неисправности тормозной системы?',
'["Прекратить движение, если неисправность создаёт угрозу безопасности, и устранить её либо вызвать эвакуатор","Игнорировать сигнал, если тормоза кажутся исправными","Продолжать движение с повышенной осторожностью до конца поездки","Увеличить скорость, чтобы быстрее доехать"]'::jsonb,0,
'При обнаружении неисправности тормозной системы в пути водитель должен принять меры к её устранению, а если это невозможно, эксплуатация ТС запрещена ввиду угрозы безопасности.',6);

-- Тема 16: Ответственность водителя — топик id=16, категория id=15
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(15,16,'Какая ответственность предусмотрена за управление ТС в состоянии опьянения?',
'["Административная ответственность в виде штрафа и лишения права управления, а при повторном нарушении — уголовная","Только устное предупреждение","Только штраф без лишения прав","Ответственность не предусмотрена"]'::jsonb,0,
'Управление ТС в состоянии опьянения влечёт административный штраф и лишение права управления ТС на срок от полутора до двух лет, а при повторном нарушении — уголовную ответственность.',1),
(15,16,'Что грозит водителю за оставление места ДТП, участником которого он является?',
'["Лишение права управления ТС на срок от одного года до полутора лет или административный арест","Только устное предупреждение","Штраф без иных последствий","Ответственность не предусмотрена, если ДТП незначительное"]'::jsonb,0,
'Оставление места ДТП его участником является грубым нарушением ПДД и влечёт лишение права управления транспортными средствами на срок от одного года до полутора лет либо административный арест.',2),
(15,16,'Несёт ли ответственность водитель, передавший управление лицу без водительского удостоверения?',
'["Да, водитель, передавший управление, также несёт административную ответственность","Нет, ответственность несёт только тот, кто управлял ТС","Ответственность предусмотрена только для лица без прав","Ответственность не предусмотрена, если ДТП не произошло"]'::jsonb,0,
'Передача управления ТС лицу, не имеющему права управления, влечёт административную ответственность как для передавшего управление, так и для управлявшего.',3),
(15,16,'Что грозит за превышение установленной скорости движения на величину более 60 км/ч?',
'["Лишение права управления ТС на срок от 4 до 6 месяцев или штраф","Только устное замечание","Штраф не более 500 рублей","Ответственность не предусмотрена вне населённых пунктов"]'::jsonb,0,
'Превышение установленной скорости движения на величину более 60 км/ч влечёт наложение административного штрафа либо лишение права управления ТС.',4),
(15,16,'Предусмотрена ли ответственность за непристёгнутый ремень безопасности?',
'["Да, административный штраф","Нет, это личное дело водителя","Ответственность предусмотрена только для пассажиров","Ответственность предусмотрена только вне населённых пунктов"]'::jsonb,0,
'Управление ТС водителем, не пристегнутым ремнём безопасности, а также перевозка пассажиров, не пристёгнутых ремнями, если конструкцией предусмотрены ремни, влечёт наложение административного штрафа.',5);

-- Тема 17: Основы безопасности дорожного движения — топик id=17, категория id=16
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(16,17,'Что в первую очередь обязан сделать водитель, причастный к ДТП, в котором есть пострадавшие?',
'["Немедленно остановиться, включить аварийную сигнализацию, выставить знак аварийной остановки и принять меры для оказания первой помощи пострадавшим","Дождаться сотрудников ГИБДД, не предпринимая никаких действий","Убрать автомобиль с дороги в первую очередь","Уехать за медицинской помощью"]'::jsonb,0,
'При ДТП с пострадавшими водитель обязан немедленно остановиться, включить аварийную сигнализацию, выставить знак аварийной остановки, принять меры для оказания первой помощи, вызвать скорую помощь и полицию.',1),
(16,17,'На каком расстоянии от ТС должен быть выставлен знак аварийной остановки вне населённого пункта?',
'["Не менее 30 м","Не менее 15 м","Не менее 5 м","Не менее 50 м"]'::jsonb,0,
'Знак аварийной остановки выставляется на расстоянии не менее 15 м от ТС в населённых пунктах и не менее 30 м вне населённых пунктов.',2),
(16,17,'В каком случае водитель обязан включить аварийную сигнализацию?',
'["При ДТП, вынужденной остановке в местах, где это запрещено, при ослеплении светом фар и в других случаях, предусмотренных ПДД","Только при движении в тумане","Только на автомагистралях","Только по требованию других водителей"]'::jsonb,0,
'Аварийная сигнализация должна быть включена при ДТП, вынужденной остановке в опасном месте, ослеплении светом фар и в иных случаях, для предупреждения об опасности, которую может создать ТС.',3),
(16,17,'Что необходимо иметь в автомобиле в соответствии с требованиями безопасности при эксплуатации?',
'["Медицинскую аптечку, огнетушитель и знак аварийной остановки","Только огнетушитель","Только аптечку","Ничего из перечисленного не обязательно"]'::jsonb,0,
'Транспортное средство при эксплуатации должно быть укомплектовано медицинской аптечкой, огнетушителем и знаком аварийной остановки в соответствии с установленным перечнем.',4),
(16,17,'Как правильно действовать при ослеплении светом фар встречного автомобиля?',
'["Включить аварийную сигнализацию, снизить скорость и, не меняя полосу, остановиться","Резко затормозить на месте","Съехать на полосу встречного движения","Увеличить скорость, чтобы быстрее миновать опасный участок"]'::jsonb,0,
'При ослеплении водитель должен включить аварийную сигнализацию и, не меняя полосу движения, снизить скорость и остановиться.',5),
(16,17,'Что должен сделать водитель, обнаруживший пострадавшего человека при дорожно-транспортном происшествии, к которому он не причастен?',
'["Принять возможные меры для оказания первой помощи и вызвать скорую помощь","Проехать мимо, так как он не участник ДТП","Обязан только сообщить в полицию без иных действий","Помощь оказывать не обязан, если нет прямого указания сотрудника ГИБДД"]'::jsonb,0,
'Все водители обязаны принимать меры для оказания первой помощи пострадавшим при ДТП, вызывать скорую помощь и, если необходимо, отправлять пострадавших на попутном транспорте в ближайшее лечебное учреждение.',6);
